#!/usr/bin/env node
// Extracts the Basil icons Rack uses from YOUR copy of the Basil Icons pack (Craftwork) into
// src/components/icons/basil.generated.ts, which is git-ignored: Craftwork's licence allows
// copying icons into an app's code but not sharing the files, and this repo is public.
// Without the generated file the app falls back to lucide icons (see Icon.tsx).
//
// Usage: node scripts/basil-icons.mjs "<path to 'Basil Icons/svg'>"
//
// Only <path> elements are kept, rebuilt from validated path data with fill="currentColor",
// so the output is safe to inline.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const svgRoot = process.argv[2];
if (!svgRoot) {
  console.error('Usage: node scripts/basil-icons.mjs "<path to Basil Icons/svg>"');
  process.exit(1);
}

const map = JSON.parse(readFileSync(join(here, "../src/components/icons/basil-map.json"), "utf8"));
const PATH_DATA = /^[MmLlHhVvCcSsQqTtAaZz0-9.,\s+-eE]+$/;

function extract(file) {
  const svg = readFileSync(file, "utf8");
  if (!/viewBox="0 0 24 24"/.test(svg)) throw new Error(`${file}: expected a 24x24 viewBox`);
  const body = svg.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
  const elements = body.match(/<[a-zA-Z][^>]*>/g) ?? [];
  const paths = [];
  for (const el of elements) {
    if (!el.startsWith("<path")) throw new Error(`${file}: unsupported element ${el.slice(0, 30)}`);
    const d = el.match(/\sd="([^"]+)"/)?.[1];
    if (!d || !PATH_DATA.test(d)) throw new Error(`${file}: bad path data`);
    const stroke = el.match(/\sstroke-width="([\d.]+)"/)?.[1];
    if (/\sstroke="/.test(el) && stroke) {
      // a few icons (Cross, Plus) are drawn with a stroke instead of a filled outline
      const cap = el.match(/\sstroke-linecap="(round|square|butt)"/)?.[1] ?? "round";
      const join = el.match(/\sstroke-linejoin="(round|miter|bevel)"/)?.[1] ?? "round";
      paths.push(
        `<path d="${d}" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="${cap}" stroke-linejoin="${join}"/>`,
      );
      continue;
    }
    const evenodd = /fill-rule="evenodd"/.test(el);
    paths.push(
      `<path d="${d}"${evenodd ? ' fill-rule="evenodd" clip-rule="evenodd"' : ""} fill="currentColor"/>`,
    );
  }
  if (!paths.length) throw new Error(`${file}: no paths`);
  return paths.join("");
}

const out = {};
for (const [role, name] of Object.entries(map)) {
  if (role.startsWith("_")) continue;
  out[role] = {
    outline: extract(join(svgRoot, "Outline", `${name}.svg`)),
    solid: extract(join(svgRoot, "Solid", `${name}.svg`)),
  };
}

const target = join(here, "../src/components/icons/basil.generated.ts");
writeFileSync(
  target,
  "// GENERATED by scripts/basil-icons.mjs from the user's Basil Icons pack (Craftwork licence).\n" +
    "// Git-ignored: never commit or share. Delete it to fall back to lucide.\n" +
    `export const BASIL: Record<string, { outline: string; solid: string }> = ${JSON.stringify(out, null, 2)};\n`,
);
console.log(`Wrote ${Object.keys(out).length} icons to ${target}`);
